void driveDirectMemory(uint32_t route) {
  const auto& descriptor = kDehermRecordingRoutes[route];
  WireInput input;
  std::vector<uint32_t> roots;
  for (uint32_t index = 0; index < descriptor.argumentCount; ++index) {
    roots.push_back(input.build(kDehermRecordingShapeRefs[descriptor.argumentFirst + index], index + 1u));
  }
  if (!input.failure.empty()) {
    deherm_recording_record_results(route, DEHERM_RECORDING_TRANSPORT_DIRECT_MEMORY, 0, "",
        ("driver-error:" + input.failure).c_str());
    return;
  }
  WireOutput output;
  const auto status = deherm_script_universal_dispatch(
      descriptor.stableId,
      input.values.empty() ? nullptr : input.values.data(), static_cast<uint32_t>(input.values.size()),
      input.entries.empty() ? nullptr : input.entries.data(), static_cast<uint32_t>(input.entries.size()),
      input.strings.empty() ? nullptr : input.strings.data(), static_cast<uint32_t>(input.strings.size()),
      input.floats.empty() ? nullptr : input.floats.data(), static_cast<uint32_t>(input.floats.size()),
      input.urls.empty() ? nullptr : input.urls.data(), static_cast<uint32_t>(input.urls.size()),
      roots.empty() ? nullptr : roots.data(), static_cast<uint32_t>(roots.size()),
      output.values.data(), static_cast<uint32_t>(output.values.size()), &output.valueCount,
      output.entries.data(), static_cast<uint32_t>(output.entries.size()), &output.entryCount,
      output.strings.data(), static_cast<uint32_t>(output.strings.size()), &output.stringBytes,
      output.floats.data(), static_cast<uint32_t>(output.floats.size()), &output.floatCount,
      output.urls.data(), static_cast<uint32_t>(output.urls.size()), &output.urlCount,
      output.roots.data(), static_cast<uint32_t>(output.roots.size()), &output.resultCount,
      output.error, sizeof(output.error));
  if (status != DEHERM_SCRIPT_UNIVERSAL_OK) {
    deherm_recording_record_results(route, DEHERM_RECORDING_TRANSPORT_DIRECT_MEMORY, 0, "",
        (std::string("dispatch-error:") + output.error).c_str());
    return;
  }
  std::string specification;
  for (uint32_t index = 0; index < output.resultCount; ++index) {
    if (index) specification += " ";
    output.render(output.roots[index], specification, 0);
  }
  for (uint32_t index = 0; index < output.resultCount; ++index) {
    deherm_script_universal_release(&output.values[output.roots[index]]);
  }
  deherm_recording_record_results(route, DEHERM_RECORDING_TRANSPORT_DIRECT_MEMORY,
      output.resultCount, specification.c_str(), "ok");
}

